function safeRedirectPath(raw: string | null): string | null {
    if (raw && raw.startsWith("/") && !raw.startsWith("//"))
        return raw;
    return null;
}

function authErrorMessage(error: {
    message: string;
    code?: string;
}): string {
    if (error.code === "user_banned") {
        return "This account has been suspended. Contact your administrator.";
    }
    return error.message;
}

async function resolveLandingPath(): Promise<string> {
    try {
        const res = await fetch("/api/permissions/me", { credentials: "include" });
        if (!res.ok)
            return "/dashboard";
        const permissions = (await res.json()) as UserPermissions;
        return resolveHomePath(permissions);
    }
    catch {
        return "/dashboard";
    }
}

useEffect(() => {
    let cancelled = false;
    const supabase = createClient();
    async function finishEmailConfirmation() {
        const code = searchParams.get("code");
        const tokenHash = searchParams.get("token_hash");
        const otpType = searchParams.get("type");
        const linkError = searchParams.get("error_description") ?? searchParams.get("error");
        const hashTokens = sessionFromHash(window.location.hash);
        const fromEmailLink = Boolean(code) || Boolean(tokenHash) || Boolean(hashTokens);
        if (linkError && fromEmailLink) {
            setError(linkError.replace(/\+/g, " "));
            return;
        }
        if (!fromEmailLink)
            return;
        setConfirming(true);
        setLoading(true);
        let authError: string | null = null;
        if (hashTokens) {
            const { error: sessionError } = await supabase.auth.setSession(hashTokens);
            if (sessionError)
                authError = sessionError.message;
            else {
                window.history.replaceState(null, "", `${window.location.pathname}${window.location.search}`);
            }
        }
        else if (tokenHash && otpType) {
            const { error: otpError } = await supabase.auth.verifyOtp({
                token_hash: tokenHash,
                type: otpType as EmailOtpType,
            });
            if (otpError)
                authError = otpError.message;
        }
        else if (code) {
            const { error: exchangeError } = await supabase.auth.exchangeCodeForSession(code);
            if (exchangeError)
                authError = exchangeError.message;
        }
        if (cancelled)
            return;
        if (authError) {
            setError(authError);
            setConfirming(false);
            setLoading(false);
            return;
        }
        const { data } = await supabase.auth.getSession();
        if (cancelled)
            return;
        if (!data.session) {
            setError("Email confirmed, but we couldn't sign you in automatically. Please log in.");
            setConfirming(false);
            setLoading(false);
            return;
        }
        router.replace(safeRedirectPath(redirect) ?? (await resolveLandingPath()));
        router.refresh();
    }
    void finishEmailConfirmation();
    return () => {
        cancelled = true;
    };
}, [searchParams, redirect, router])

async function signIn(emailValue: string, passwordValue: string) {
    setError(null);
    setLoading(true);
    const supabase = createClient();
    const { error: signInError } = await supabase.auth.signInWithPassword({
        email: emailValue,
        password: passwordValue,
    });
    if (signInError) {
        void fetch("/api/auth/login-failed", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ email: emailValue }),
        }).catch(() => { });
        setError(authErrorMessage(signInError));
        setLoading(false);
        return;
    }
    await fetch("/api/auth/session-event", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ event: "login" }),
    }).catch(() => { });
    router.push(redirect ?? (await resolveLandingPath()));
    router.refresh();
}

async function handleSubmit(e: FormEvent) {
    e.preventDefault();
    void signIn(email, password);
}

